      ro: ["Unul dintre cei mai mari angajatori din Cavite.", "Se concentrează pe producția orientată spre export.", "Contribuie semnificativ la economia filipineză."],
      en: ["One of the largest employers in Cavite.", "Focuses on export-oriented manufacturing.", "Contributes significantly to the Philippine economy."],
