      ro: "Una dintre cele mai importante hidrocentrale de pe râul Agus din Iligan City, furnizând o mare parte din energia electrică pentru Mindanao.",
      en: "One of the key hydroelectric plants on the Agus River in Iligan City, providing a large portion of Mindanao's electricity.",
      es: "Una de las centrales hidroeléctricas más importantes del río Agus en Iligan City, que suministra gran parte de la electricidad de Mindanao.",
