      hu: "Központi üzleti negyed Muntinlupa Cityben, Metro Manilában, amely a fenntarthatóságra és a környezetbarát fejlesztésre összpontosít.",
      ro: "Un district central de afaceri în Muntinlupa City, Metro Manila, axat pe durabilitate și dezvoltare ecologică.",
