      hu: ["A Fülöp-szigetek a világ egyik legnagyobb nikkelérctermelője.", "A bányászat fontos, de ellentmondásos iparág a régióban.", "Az ércet elsősorban Kínába exportálják."],
      ro: ["Filipine este unul dintre cei mai mari producători de minereu de nichel din lume.", "Mineritul este o industrie majoră, dar controversată în regiune.", "Minereul este exportat în principal în China."],
      en: ["The Philippines is one of the world's top nickel ore producers.", "Mining is a major but controversial industry in the region.", "Ore is primarily exported to China."],
